     1→import {SLOTS_PER_EPOCH} from "@lodestar/params";
     2→import {Epoch, SignedBeaconBlock, SignedBlindedBeaconBlock, Slot, ssz} from "@lodestar/types";
     3→import {toRootHex} from "@lodestar/utils";
     4→import {BlockExternalData, DataAvailabilityStatus, ExecutionPayloadStatus} from "./block/externalData.js";
     5→import {processBlock} from "./block/index.js";
     6→import {ProcessBlockOpts} from "./block/types.js";
     7→import {EpochTransitionCache, EpochTransitionCacheOpts, beforeProcessEpoch} from "./cache/epochTransitionCache.js";
     8→import {EpochTransitionStep, processEpoch} from "./epoch/index.js";
     9→import {BeaconStateTransitionMetrics, onPostStateMetrics, onStateCloneMetrics} from "./metrics.js";
    10→import {verifyProposerSignature} from "./signatureSets/index.js";
    11→import {
    12→  processSlot,
    13→  upgradeStateToAltair,
    14→  upgradeStateToBellatrix,
    15→  upgradeStateToCapella,
    16→  upgradeStateToDeneb,
    17→  upgradeStateToElectra,
    18→  upgradeStateToGloas,
    19→} from "./slot/index.js";
    20→import {upgradeStateToFulu} from "./slot/upgradeStateToFulu.js";
    21→import {
    22→  CachedBeaconStateAllForks,
    23→  CachedBeaconStateAltair,
    24→  CachedBeaconStateBellatrix,
    25→  CachedBeaconStateCapella,
    26→  CachedBeaconStateDeneb,
    27→  CachedBeaconStateElectra,
    28→  CachedBeaconStateFulu,
    29→  CachedBeaconStatePhase0,
    30→} from "./types.js";
    31→import {computeEpochAtSlot} from "./util/index.js";
    32→
    33→// Multifork capable state transition
    34→
    35→// NOTE DENEB: Mandatory BlockExternalData to decide if block is available or not
    36→export type StateTransitionOpts = BlockExternalData &
    37→  EpochTransitionCacheOpts &
    38→  ProcessBlockOpts & {
    39→    verifyStateRoot?: boolean;
    40→    verifyProposer?: boolean;
    41→    verifySignatures?: boolean;
    42→    dontTransferCache?: boolean;
    43→  };
    44→
    45→export type StateTransitionModules = {
    46→  metrics?: BeaconStateTransitionMetrics | null;
    47→  validatorMonitor?: ValidatorMonitor | null;
    48→};
    49→
    50→interface ValidatorMonitor {
    51→  registerValidatorStatuses(
    52→    currentEpoch: Epoch,
    53→    inclusionDelays: number[],
    54→    flags: number[],
    55→    isActiveCurrEpoch: boolean[],
    56→    isActivePrevEpoch: boolean[],
    57→    balances?: number[]
    58→  ): void;
    59→}
    60→
    61→/**
    62→ * `state.clone()` invocation source tracked in metrics
    63→ */
    64→export enum StateCloneSource {
    65→  stateTransition = "stateTransition",
    66→  processSlots = "processSlots",
    67→}
    68→
    69→/**
    70→ * `state.hashTreeRoot()` invocation source tracked in metrics
    71→ */
    72→export enum StateHashTreeRootSource {
    73→  stateTransition = "state_transition",
    74→  blockTransition = "block_transition",
    75→  prepareNextSlot = "prepare_next_slot",
    76→  prepareNextEpoch = "prepare_next_epoch",
    77→  regenState = "regen_state",
    78→  computeNewStateRoot = "compute_new_state_root",
    79→}
    80→
    81→/**
    82→ * Implementation Note: follows the optimizations in protolambda's eth2fastspec (https://github.com/protolambda/eth2fastspec)
    83→ */
    84→export function stateTransition(
    85→  state: CachedBeaconStateAllForks,
    86→  signedBlock: SignedBeaconBlock | SignedBlindedBeaconBlock,
    87→  options: StateTransitionOpts = {
    88→    // Assume default to be valid and available
    89→    executionPayloadStatus: ExecutionPayloadStatus.valid,
    90→    dataAvailabilityStatus: DataAvailabilityStatus.Available,
    91→  },
    92→  {metrics, validatorMonitor}: StateTransitionModules = {}
    93→): CachedBeaconStateAllForks {
    94→  const {verifyStateRoot = true, verifyProposer = true} = options;
    95→
    96→  const block = signedBlock.message;
    97→  const blockSlot = block.slot;
    98→
    99→  // .clone() before mutating state in state transition
   100→  let postState = state.clone(options.dontTransferCache);
   101→
   102→  if (metrics) {
   103→    onStateCloneMetrics(postState, metrics, StateCloneSource.stateTransition);
   104→  }
   105→
   106→  // State is already a ViewDU, which won't commit changes. Equivalent to .setStateCachesAsTransient()
   107→  // postState.setStateCachesAsTransient();
   108→
   109→  // Process slots (including those with no blocks) since block.
   110→  // Includes state upgrades
   111→  postState = processSlotsWithTransientCache(postState, blockSlot, options, {metrics, validatorMonitor});
   112→
   113→  // Verify proposer signature only
   114→  if (verifyProposer && !verifyProposerSignature(postState, signedBlock)) {
   115→    throw new Error("Invalid block signature");
   116→  }
   117→
   118→  // Process block
   119→  const fork = state.config.getForkSeq(block.slot);
   120→
   121→  // Note: time only on success
   122→  const processBlockTimer = metrics?.processBlockTime.startTimer();
   123→
   124→  processBlock(fork, postState, block, options, options, metrics);
   125→
   126→  const processBlockCommitTimer = metrics?.processBlockCommitTime.startTimer();
   127→  postState.commit();
   128→  processBlockCommitTimer?.();
   129→
   130→  // Note: time only on success. Include processBlock and commit
   131→  processBlockTimer?.();
   132→
   133→  if (metrics) {
   134→    onPostStateMetrics(postState, metrics);
   135→  }
   136→
   137→  // Verify state root
   138→  if (verifyStateRoot) {
   139→    const hashTreeRootTimer = metrics?.stateHashTreeRootTime.startTimer({
   140→      source: StateHashTreeRootSource.stateTransition,
   141→    });
   142→    const stateRoot = postState.hashTreeRoot();
   143→    hashTreeRootTimer?.();
   144→
   145→    if (!ssz.Root.equals(block.stateRoot, stateRoot)) {
   146→      throw new Error(
   147→        `Invalid state root at slot ${block.slot}, expected=${toRootHex(block.stateRoot)}, actual=${toRootHex(
   148→          stateRoot
   149→        )}`
   150→      );
   151→    }
   152→  }
   153→
   154→  return postState;
   155→}
   156→
   157→/**
   158→ * Like `processSlots` from the spec but additionally handles fork upgrades
   159→ *
   160→ * Implementation Note: follows the optimizations in protolambda's eth2fastspec (https://github.com/protolambda/eth2fastspec)
   161→ */
   162→export function processSlots(
   163→  state: CachedBeaconStateAllForks,
   164→  slot: Slot,
   165→  epochTransitionCacheOpts?: EpochTransitionCacheOpts & {dontTransferCache?: boolean},
   166→  {metrics, validatorMonitor}: StateTransitionModules = {}
   167→): CachedBeaconStateAllForks {
   168→  // .clone() before mutating state in state transition
   169→  let postState = state.clone(epochTransitionCacheOpts?.dontTransferCache);
   170→
   171→  if (metrics) {
   172→    onStateCloneMetrics(postState, metrics, StateCloneSource.processSlots);
   173→  }
   174→
   175→  // State is already a ViewDU, which won't commit changes. Equivalent to .setStateCachesAsTransient()
   176→  // postState.setStateCachesAsTransient();
   177→
   178→  postState = processSlotsWithTransientCache(postState, slot, epochTransitionCacheOpts, {metrics, validatorMonitor});
   179→
   180→  // Apply changes to state, must do before hashing
   181→  postState.commit();
   182→
   183→  return postState;
   184→}
   185→
   186→/**
   187→ * All processSlot() logic but separate so stateTransition() can recycle the caches
   188→ *
   189→ * Epoch transition will be processed at the last slot of an epoch. Note that compute_shuffling() is going
   190→ * to be executed in parallel (either by napi-rs or worker thread) with processEpoch() like below:
   191→ *
   192→ *   state-transition
   193→ *   ╔══════════════════════════════════════════════════════════════════════════════════╗
   194→ *   ║   beforeProcessEpoch          processEpoch                 afterPRocessEpoch     ║
   195→ *   ║  |-------------------------|--------------------|-------------------------------|║
   196→ *   ║                       |                         |     |                          ║
   197→ *   ╚═══════════════════════|═══════════════════════════════|══════════════════════════╝
   198→ *                           |                               |
   199→ *                         build()                          get()
   200→ *                           |                               |
   201→ *   ╔═══════════════════════V═══════════════════════════════V═══════════════════════════╗
   202→ *   ║                       |                               |                           ║
   203→ *   ║                       |-------------------------------|                           ║
   204→ *   ║                          compute_shuffling()                                      ║
   205→ *   ╚═══════════════════════════════════════════════════════════════════════════════════╝
   206→ *   beacon-node ShufflingCache
   207→ */
   208→function processSlotsWithTransientCache(
   209→  postState: CachedBeaconStateAllForks,
   210→  slot: Slot,
   211→  epochTransitionCacheOpts?: EpochTransitionCacheOpts,
   212→  {metrics, validatorMonitor}: StateTransitionModules = {}
   213→): CachedBeaconStateAllForks {
   214→  const {config} = postState;
   215→  if (postState.slot > slot) {
   216→    throw Error(`Too old slot ${slot}, current=${postState.slot}`);
   217→  }
   218→
   219→  while (postState.slot < slot) {
   220→    processSlot(postState);
   221→
   222→    // Process epoch on the first slot of the next epoch
   223→    if ((postState.slot + 1) % SLOTS_PER_EPOCH === 0) {
   224→      // At fork boundary we don't want to process "next fork" epoch before upgrading state
   225→      const fork = postState.config.getForkSeq(postState.slot);
   226→
   227→      const epochTransitionTimer = metrics?.epochTransitionTime.startTimer();
   228→
   229→      let epochTransitionCache: EpochTransitionCache;
   230→      {
   231→        const timer = metrics?.epochTransitionStepTime.startTimer({step: EpochTransitionStep.beforeProcessEpoch});
   232→        epochTransitionCache = beforeProcessEpoch(postState, epochTransitionCacheOpts);
   233→        timer?.();
   234→      }
   235→
   236→      processEpoch(fork, postState, epochTransitionCache, metrics);
   237→
   238→      const {currentEpoch, inclusionDelays, flags, isActiveCurrEpoch, isActivePrevEpoch, balances} =
   239→        epochTransitionCache;
   240→      validatorMonitor?.registerValidatorStatuses(
   241→        currentEpoch,
   242→        inclusionDelays,
   243→        flags,
   244→        isActiveCurrEpoch,
   245→        isActivePrevEpoch,
   246→        balances
   247→      );
   248→
   249→      postState.slot++;
   250→
   251→      {
   252→        const timer = metrics?.epochTransitionStepTime.startTimer({step: EpochTransitionStep.afterProcessEpoch});
   253→        // this should be called before `upgradeState*()` below to prepare data for it
   254→        postState.epochCtx.afterProcessEpoch(postState, epochTransitionCache);
   255→        timer?.();
   256→      }
   257→
   258→      // Upgrade state if exactly at epoch boundary
   259→      const stateEpoch = computeEpochAtSlot(postState.slot);
   260→      if (stateEpoch === config.ALTAIR_FORK_EPOCH) {
   261→        postState = upgradeStateToAltair(postState as CachedBeaconStatePhase0) as CachedBeaconStateAllForks;
   262→      }
   263→      if (stateEpoch === config.BELLATRIX_FORK_EPOCH) {
   264→        postState = upgradeStateToBellatrix(postState as CachedBeaconStateAltair) as CachedBeaconStateAllForks;
