   116→    // SAMPLES_PER_SLOT is in columns, and CUSTODY_GROUP_COUNT is in groups
   117→    this.sampledGroupCount = Math.max(this.targetCustodyGroupCount, this.config.SAMPLES_PER_SLOT);
   118→    this.sampleGroups = getCustodyGroups(this.config, this.nodeId, this.sampledGroupCount);
   119→    this.sampledColumns = getDataColumns(this.config, this.nodeId, this.sampledGroupCount);
