   137→
   138→function computeSubnetForDataColumn(config: ChainForkConfig, columnIndex: ColumnIndex): number {
   139→  return columnIndex % config.DATA_COLUMN_SIDECAR_SUBNET_COUNT;
   140→}
   141→
   142→/**
   143→ * Calculate the number of custody groups the node should subscribe to based on the node's effective balance
   144→ *
   145→ * SPEC FUNCTION
   146→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/validator.md#validator-custody
   147→ */
   148→export function getValidatorsCustodyRequirement(config: ChainForkConfig, effectiveBalances: number[]): number {
   149→  if (effectiveBalances.length === 0) {
   150→    return config.CUSTODY_REQUIREMENT;
   151→  }
   152→
   153→  const totalNodeEffectiveBalance = effectiveBalances.reduce((total, effectiveBalance) => {
   154→    return total + effectiveBalance;
   155→  }, 0);
   156→
   157→  // Must custody one group for every BALANCE_PER_ADDITIONAL_CUSTODY_GROUP of effective balance
   158→  let validatorsCustodyRequirement = Math.floor(
   159→    totalNodeEffectiveBalance / config.BALANCE_PER_ADDITIONAL_CUSTODY_GROUP
   160→  );
   161→
   162→  // Any node with at least 1 validator must custody at least VALIDATOR_CUSTODY_REQUIREMENT
   163→  validatorsCustodyRequirement = Math.max(validatorsCustodyRequirement, config.VALIDATOR_CUSTODY_REQUIREMENT);
   164→
   165→  // Cannot custody more than NUMBER_OF_CUSTODY_GROUPS
   166→  validatorsCustodyRequirement = Math.min(validatorsCustodyRequirement, config.NUMBER_OF_CUSTODY_GROUPS);
   167→
   168→  return validatorsCustodyRequirement;
   169→}
   170→
   171→/**
   172→ * Converts a custody group to an array of column indices.  Should be 1-1 as long there are 128
   173→ * columns and 128 custody groups.
   174→ *
   175→ * SPEC FUNCTION
   176→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#compute_columns_for_custody_group
   177→ */
   178→export function computeColumnsForCustodyGroup(config: ChainForkConfig, custodyIndex: CustodyIndex): ColumnIndex[] {
   179→  if (custodyIndex > config.NUMBER_OF_CUSTODY_GROUPS) {
   180→    throw Error(`Invalid custody index ${custodyIndex} > ${config.NUMBER_OF_CUSTODY_GROUPS}`);
   181→  }
   182→  const columnsPerCustodyGroup = Number(NUMBER_OF_COLUMNS / config.NUMBER_OF_CUSTODY_GROUPS);
   183→  const columnIndexes = [];
   184→  for (let i = 0; i < columnsPerCustodyGroup; i++) {
   185→    columnIndexes.push(config.NUMBER_OF_CUSTODY_GROUPS * i + custodyIndex);
   186→  }
   187→  columnIndexes.sort((a, b) => a - b);
   188→  return columnIndexes;
   189→}
   190→
   191→/**
   192→ * Converts nodeId and a the number of custody groups to an array of custody indices. Indexes must be
   193→ * further converted to column indices
   194→ *
   195→ * SPEC FUNCTION
   196→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#get_custody_groups
   197→ */
   198→export function getCustodyGroups(config: ChainForkConfig, nodeId: NodeId, custodyGroupCount: number): CustodyIndex[] {
   199→  if (custodyGroupCount > config.NUMBER_OF_CUSTODY_GROUPS) {
   200→    throw Error(`Invalid custody group count ${custodyGroupCount} > ${config.NUMBER_OF_CUSTODY_GROUPS}`);
   201→  }
   202→
   203→  // Skip computation if all groups are custodied
   204→  if (custodyGroupCount === config.NUMBER_OF_CUSTODY_GROUPS) {
   205→    return Array.from({length: config.NUMBER_OF_CUSTODY_GROUPS}, (_, i) => i);
   206→  }
   207→
   208→  const custodyGroups: CustodyIndex[] = [];
   209→  // nodeId is in bigendian and all computes are in little endian
   210→  let currentId = bytesToBigInt(nodeId, "be");
   211→  while (custodyGroups.length < custodyGroupCount) {
   212→    // could be optimized
   213→    const currentIdBytes = ssz.UintBn256.serialize(currentId);
   214→    const custodyGroup = Number(
   215→      ssz.UintBn64.deserialize(digest(currentIdBytes).slice(0, 8)) % BigInt(config.NUMBER_OF_CUSTODY_GROUPS)
   216→    );
   217→
   218→    if (!custodyGroups.includes(custodyGroup)) {
   219→      custodyGroups.push(custodyGroup);
   220→    }
   221→
   222→    const willOverflow = currentIdBytes.reduce((acc, elem) => acc && elem === 0xff, true);
   223→    if (willOverflow) {
   224→      currentId = BigInt(0);
   225→    } else {
   226→      currentId++;
   227→    }
   228→  }
   229→
   230→  custodyGroups.sort((a, b) => a - b);
   231→  return custodyGroups;
   232→}
   233→
   234→export function computeKzgCommitmentsInclusionProof(
   235→  fork: ForkName,
   236→  body: BeaconBlockBody
   237→): fulu.KzgCommitmentsInclusionProof {
   238→  const bodyView = (ssz[fork].BeaconBlockBody as SSZTypesFor<ForkAll, "BeaconBlockBody">).toView(body);
   239→  return new Tree(bodyView.node).getSingleProof(BigInt(KZG_COMMITMENTS_GINDEX));
   240→}
   241→
   242→export function getDataColumns(config: ChainForkConfig, nodeId: NodeId, custodyGroupCount: number): ColumnIndex[] {
   243→  return getCustodyGroups(config, nodeId, custodyGroupCount)
   244→    .flatMap((custodyIndex) => computeColumnsForCustodyGroup(config, custodyIndex))
   245→    .sort((a, b) => a - b);
   246→}
   247→
   248→/**
   249→ * Computes the cells for each blob and combines them with cell proofs.
   250→ * Similar to the computeMatrix function described below.
   251→ *
   252→ * SPEC FUNCTION (note: spec currently computes proofs, but we already have them)
   253→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#compute_matrix
   254→ */
   255→export function getCellsAndProofs(blobBundles: fulu.BlobAndProofV2[]): {cells: Uint8Array[]; proofs: Uint8Array[]}[] {
   256→  return blobBundles.map(({blob, proofs}) => {
   257→    const cells = kzg.computeCells(blob);
   258→    return {cells, proofs};
   259→  });
   260→}
   261→
   262→/**
   263→ * Given a signed block header and the commitments, inclusion proof, cells/proofs associated with
   264→ * each blob in the block, assemble the sidecars which can be distributed to peers.
   265→ *
   266→ * SPEC FUNCTION
   267→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/validator.md#get_data_column_sidecars
   268→ */
   269→export function getDataColumnSidecars(
   270→  signedBlockHeader: SignedBeaconBlockHeader,
   271→  kzgCommitments: deneb.KZGCommitment[],
   272→  kzgCommitmentsInclusionProof: fulu.KzgCommitmentsInclusionProof,
   273→  cellsAndKzgProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[]
   274→): fulu.DataColumnSidecars {
   275→  if (cellsAndKzgProofs.length !== kzgCommitments.length) {
   276→    throw Error("Invalid cellsAndKzgProofs length for getDataColumnSidecars");
   277→  }
   278→
   279→  const sidecars: fulu.DataColumnSidecars = [];
   280→  for (let columnIndex = 0; columnIndex < NUMBER_OF_COLUMNS; columnIndex++) {
   281→    const columnCells = [];
   282→    const columnProofs = [];
   283→    for (const {cells, proofs} of cellsAndKzgProofs) {
   284→      columnCells.push(cells[columnIndex]);
   285→      columnProofs.push(proofs[columnIndex]);
   286→    }
   287→    sidecars.push({
   288→      index: columnIndex,
   289→      column: columnCells,
   290→      kzgCommitments,
   291→      kzgProofs: columnProofs,
   292→      signedBlockHeader,
   293→      kzgCommitmentsInclusionProof,
   294→    });
   295→  }
   296→  return sidecars;
   297→}
   298→
   299→/**
   300→ * Given a signed block and the cells/proofs associated with each blob in the
   301→ * block, assemble the sidecars which can be distributed to peers.
   302→ *
   303→ * SPEC FUNCTION
   304→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/validator.md#get_data_column_sidecars_from_block
   305→ */
   306→export function getDataColumnSidecarsFromBlock(
   307→  config: ChainForkConfig,
   308→  signedBlock: SignedBeaconBlock<ForkPostFulu>,
   309→  cellsAndKzgProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[]
   310→): fulu.DataColumnSidecars {
   311→  const blobKzgCommitments = signedBlock.message.body.blobKzgCommitments;
   312→
   313→  // No need to create data column sidecars if there are no blobs
   314→  if (blobKzgCommitments.length === 0) {
   315→    return [];
   316→  }
   317→
   318→  const fork = config.getForkName(signedBlock.message.slot);
   319→  const signedBlockHeader = signedBlockToSignedHeader(config, signedBlock);
   320→
   321→  const kzgCommitmentsInclusionProof = computeKzgCommitmentsInclusionProof(fork, signedBlock.message.body);
   322→
   323→  return getDataColumnSidecars(signedBlockHeader, blobKzgCommitments, kzgCommitmentsInclusionProof, cellsAndKzgProofs);
   324→}
   325→
   326→/**
   327→ * Given a DataColumnSidecar and the cells/proofs associated with each blob corresponding
   328→ * to the commitments it contains, assemble all sidecars for distribution to peers.
   329→ *
   330→ * SPEC FUNCTION
   331→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/validator.md#get_data_column_sidecars_from_column_sidecar
   332→ */
   333→export function getDataColumnSidecarsFromColumnSidecar(
   334→  sidecar: fulu.DataColumnSidecar,
   335→  cellsAndKzgProofs: {cells: Uint8Array[]; proofs: Uint8Array[]}[]
   336→): fulu.DataColumnSidecars {
   337→  return getDataColumnSidecars(
   338→    sidecar.signedBlockHeader,
   339→    sidecar.kzgCommitments,
   340→    sidecar.kzgCommitmentsInclusionProof,
   341→    cellsAndKzgProofs
   342→  );
   343→}
   344→
   345→/**
   346→ * If we receive more than half of NUMBER_OF_COLUMNS (64) we should recover all remaining columns
   347→ */
   348→export async function recoverDataColumnSidecars(
   349→  dataColumnCache: DataColumnsCacheMap,
   350→  clock: IClock,
   351→  metrics: Metrics | null
   352→): Promise<RecoverResult> {
   353→  const columnCount = dataColumnCache.size;
   354→  if (columnCount >= NUMBER_OF_COLUMNS) {
   355→    // We have all columns
   356→    return RecoverResult.NotAttemptedFull;
   357→  }
   358→
   359→  if (columnCount < NUMBER_OF_COLUMNS / 2) {
   360→    // We don't have enough columns to recover
   361→    return RecoverResult.NotAttemptedLessThanHalf;
   362→  }
   363→
   364→  const partialColumns = dataColumnCache.size;
   365→  metrics?.recoverDataColumnSidecars.custodyBeforeReconstruction.set(partialColumns);
   366→  const partialSidecars = new Map<number, fulu.DataColumnSidecar>();
   367→  for (const [columnIndex, {dataColumn}] of dataColumnCache.entries()) {
   368→    // the more columns we put, the slower the recover
   369→    if (partialSidecars.size >= NUMBER_OF_COLUMNS / 2) {
   370→      break;
   371→    }
   372→    partialSidecars.set(columnIndex, dataColumn);
   373→  }
   374→
   375→  const timer = metrics?.peerDas.dataColumnsReconstructionTime.startTimer();
   376→  // if this function throws, we catch at the consumer side
   377→  const fullSidecars = await recover(partialSidecars);
   378→  timer?.();
   379→  if (fullSidecars == null) {
   380→    return RecoverResult.Failed;
   381→  }
   382→
   383→  const firstDataColumn = dataColumnCache.values().next().value?.dataColumn;
   384→  if (firstDataColumn == null) {
   385→    // should not happen because we checked the size of the cache before this
   386→    throw new Error("No data column found in cache to recover from");
   387→  }
   388→
   389→  const slot = firstDataColumn.signedBlockHeader.message.slot;
   390→  const secFromSlot = clock.secFromSlot(slot);
   391→  metrics?.recoverDataColumnSidecars.elapsedTimeTillReconstructed.observe(secFromSlot);
   392→
   393→  if (dataColumnCache.size === NUMBER_OF_COLUMNS) {
   394→    // either gossip or getBlobsV2 resolved availability while we were recovering
   395→    return RecoverResult.SuccessLate;
   396→  }
   397→
   398→  // We successfully recovered the data columns, update the cache
   399→  for (let columnIndex = 0; columnIndex < NUMBER_OF_COLUMNS; columnIndex++) {
   400→    if (dataColumnCache.has(columnIndex)) {
   401→      // We already have this column
   402→      continue;
   403→    }
   404→
   405→    const sidecar = fullSidecars[columnIndex];
   406→    if (sidecar === undefined) {
   407→      throw new Error(`full sidecars is undefined at index ${columnIndex}`);
   408→    }
   409→    dataColumnCache.set(columnIndex, {dataColumn: sidecar, dataColumnBytes: null});
   410→    metrics?.peerDas.reconstructedColumns.inc(NUMBER_OF_COLUMNS - partialColumns);
   411→  }
   412→
   413→  return RecoverResult.SuccessResolved;
   414→}
   415→
   416→export function hasSampledDataColumns(custodyConfig: CustodyConfig, dataColumnCache: DataColumnsCacheMap): boolean {
   417→  return (
   418→    dataColumnCache.size >= custodyConfig.sampledColumns.length &&
   419→    custodyConfig.sampledColumns.reduce((acc, columnIndex) => acc && dataColumnCache.has(columnIndex), true)
   420→  );
   421→}
   422→
   423→export async function getDataColumnsFromExecution(
   424→  config: ChainForkConfig,
   425→  custodyConfig: CustodyConfig,
   426→  executionEngine: IExecutionEngine,
   427→  emitter: ChainEventEmitter,
   428→  blockCache: BlockInputCacheType,
   429→  metrics: Metrics | null
   430→): Promise<boolean> {
   431→  if (blockCache.fork !== ForkName.fulu) {
   432→    return false;
   433→  }
   434→
   435→  if (!blockCache.cachedData) {
   436→    // this condition should never get hit... just a sanity check
   437→    throw new Error("invalid blockCache");
   438→  }
   439→
   440→  if (blockCache.cachedData.fork !== ForkName.fulu) {
   441→    return false;
   442→  }
   443→
   444→  // If already have all columns, exit
   445→  if (hasSampledDataColumns(custodyConfig, blockCache.cachedData.dataColumnsCache)) {
   446→    return true;
   447→  }
   448→
   449→  let commitments: undefined | Uint8Array[];
   450→  if (blockCache.block) {
   451→    const block = blockCache.block as fulu.SignedBeaconBlock;
   452→    commitments = block.message.body.blobKzgCommitments;
   453→  } else {
   454→    const firstSidecar = blockCache.cachedData.dataColumnsCache.values().next().value;
   455→    commitments = firstSidecar?.dataColumn.kzgCommitments;
   456→  }
   457→
   458→  if (!commitments) {
   459→    throw new Error("blockInputCache missing both block and cachedData");
   460→  }
   461→
   462→  // Return if block has no blobs
   463→  if (commitments.length === 0) {
   464→    return true;
   465→  }
   466→
   467→  // Process KZG commitments into versioned hashes
   468→  const versionedHashes: Uint8Array[] = commitments.map(kzgCommitmentToVersionedHash);
   469→
   470→  // Get blobs from execution engine
   471→  metrics?.peerDas.getBlobsV2Requests.inc();
   472→  const timer = metrics?.peerDas.getBlobsV2RequestDuration.startTimer();
   473→  const blobs = await executionEngine.getBlobs(blockCache.fork, versionedHashes);
   474→  timer?.();
   475→
   476→  // Execution engine was unable to find one or more blobs
   477→  if (blobs === null) {
   478→    return false;
   479→  }
   480→  metrics?.peerDas.getBlobsV2Responses.inc();
   481→
   482→  // Return if we received all data columns while waiting for getBlobs
   483→  if (hasSampledDataColumns(custodyConfig, blockCache.cachedData.dataColumnsCache)) {
   484→    return true;
   485→  }
   486→
   487→  let dataColumnSidecars: fulu.DataColumnSidecars;
   488→  const cellsAndProofs = getCellsAndProofs(blobs);
   489→  if (blockCache.block) {
   490→    dataColumnSidecars = getDataColumnSidecarsFromBlock(
   491→      config,
   492→      blockCache.block as fulu.SignedBeaconBlock,
   493→      cellsAndProofs
   494→    );
   495→  } else {
   496→    const firstSidecar = blockCache.cachedData.dataColumnsCache.values().next().value;
   497→    if (!firstSidecar) {
   498→      throw new Error("blockInputCache missing both block and data column sidecar");
   499→    }
   500→    dataColumnSidecars = getDataColumnSidecarsFromColumnSidecar(firstSidecar.dataColumn, cellsAndProofs);
   501→  }
   502→
   503→  // Publish columns if and only if subscribed to them
   504→  const sampledColumns = custodyConfig.sampledColumns.map((columnIndex) => dataColumnSidecars[columnIndex]);
   505→
   506→  // for columns that we already seen, it will be ignored through `ignoreDuplicatePublishError` gossip option
   507→  emitter.emit(ChainEvent.publishDataColumns, sampledColumns);
   508→
   509→  for (const column of sampledColumns) {
   510→    blockCache.cachedData.dataColumnsCache.set(column.index, {dataColumn: column, dataColumnBytes: null});
   511→  }
   512→
   513→  const allDataColumns = getBlockInputDataColumns(blockCache.cachedData.dataColumnsCache, custodyConfig.sampledColumns);
   514→  // TODO: Add metrics
   515→  // metrics?.syncUnknownBlock.resolveAvailabilitySource.inc({source: BlockInputAvailabilitySource.GOSSIP});
   516→  const blockData: BlockInputDataColumns = {
   517→    fork: blockCache.cachedData.fork,
   518→    ...allDataColumns,
   519→    dataColumnsSource: DataColumnsSource.engine,
   520→  };
   521→  const partialColumns = blockCache.cachedData.dataColumnsCache.size;
   522→  blockCache.cachedData.resolveAvailability(blockData);
   523→  metrics?.dataColumns.bySource.inc({source: DataColumnsSource.engine}, NUMBER_OF_COLUMNS - partialColumns);
   524→
   525→  if (blockCache.block !== undefined) {
   526→    const blockInput = getBlockInput.availableData(config, blockCache.block, BlockSource.gossip, blockData);
   527→
   528→    blockCache.resolveBlockInput(blockInput);
   529→  }
   530→
   531→  return true;
   532→}
   533→

