     1→import {ChainConfig} from "@lodestar/config";
     2→import {
     3→  KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH,
     4→  KZG_COMMITMENTS_SUBTREE_INDEX,
     5→  NUMBER_OF_COLUMNS,
     6→} from "@lodestar/params";
     7→import {Root, Slot, SubnetID, deneb, fulu, ssz} from "@lodestar/types";
     8→import {toRootHex, verifyMerkleBranch} from "@lodestar/utils";
     9→
    10→import {computeStartSlotAtEpoch, getBlockHeaderProposerSignatureSet} from "@lodestar/state-transition";
    11→import {Metrics} from "../../metrics/metrics.js";
    12→import {byteArrayEquals} from "../../util/bytes.js";
    13→import {kzg} from "../../util/kzg.js";
    14→import {DataColumnSidecarErrorCode, DataColumnSidecarGossipError} from "../errors/dataColumnSidecarError.js";
    15→import {GossipAction} from "../errors/gossipValidation.js";
    16→import {IBeaconChain} from "../interface.js";
    17→import {RegenCaller} from "../regen/interface.js";
    18→
    19→// SPEC FUNCTION
    20→// https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#data_column_sidecar_subnet_id
    21→export async function validateGossipDataColumnSidecar(
    22→  chain: IBeaconChain,
    23→  dataColumnSidecar: fulu.DataColumnSidecar,
    24→  gossipSubnet: SubnetID,
    25→  metrics: Metrics | null
    26→): Promise<void> {
    27→  const blockHeader = dataColumnSidecar.signedBlockHeader.message;
    28→
    29→  // 1) [REJECT] The sidecar is valid as verified by verify_data_column_sidecar
    30→  verifyDataColumnSidecar(dataColumnSidecar);
    31→
    32→  // 2) [REJECT] The sidecar is for the correct subnet -- i.e. compute_subnet_for_data_column_sidecar(sidecar.index) == subnet_id
    33→  if (computeSubnetForDataColumnSidecar(chain.config, dataColumnSidecar) !== gossipSubnet) {
    34→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
    35→      code: DataColumnSidecarErrorCode.INVALID_SUBNET,
    36→      columnIdx: dataColumnSidecar.index,
    37→      gossipSubnet: gossipSubnet,
    38→    });
    39→  }
    40→
    41→  // 3) [IGNORE] The sidecar is not from a future slot (with a MAXIMUM_GOSSIP_CLOCK_DISPARITY allowance)
    42→  //             -- i.e. validate that sidecar.slot <= current_slot (a client MAY queue future blocks
    43→  //             for processing at the appropriate slot).
    44→  const currentSlotWithGossipDisparity = chain.clock.currentSlotWithGossipDisparity;
    45→  if (currentSlotWithGossipDisparity < blockHeader.slot) {
    46→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    47→      code: DataColumnSidecarErrorCode.FUTURE_SLOT,
    48→      currentSlot: currentSlotWithGossipDisparity,
    49→      blockSlot: blockHeader.slot,
    50→    });
    51→  }
    52→
    53→  // 4) [IGNORE] The sidecar is from a slot greater than the latest finalized slot -- i.e. validate that
    54→  //             sidecar.slot > compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)
    55→  const finalizedCheckpoint = chain.forkChoice.getFinalizedCheckpoint();
    56→  const finalizedSlot = computeStartSlotAtEpoch(finalizedCheckpoint.epoch);
    57→  if (blockHeader.slot <= finalizedSlot) {
    58→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    59→      code: DataColumnSidecarErrorCode.WOULD_REVERT_FINALIZED_SLOT,
    60→      blockSlot: blockHeader.slot,
    61→      finalizedSlot,
    62→    });
    63→  }
    64→
    65→  // 6) [IGNORE] The sidecar's block's parent (defined by block_header.parent_root) has been seen (via gossip
    66→  //             or non-gossip sources)
    67→  const parentRoot = toRootHex(blockHeader.parentRoot);
    68→  const parentBlock = chain.forkChoice.getBlockHex(parentRoot);
    69→  if (parentBlock === null) {
    70→    // If fork choice does *not* consider the parent to be a descendant of the finalized block,
    71→    // then there are two more cases:
    72→    //
    73→    // 1. We have the parent stored in our database. Because fork-choice has confirmed the
    74→    //    parent is *not* in our post-finalization DAG, all other blocks must be either
    75→    //    pre-finalization or conflicting with finalization.
    76→    // 2. The parent is unknown to us, we probably want to download it since it might actually
    77→    //    descend from the finalized root.
    78→    // (Non-Lighthouse): Since we prune all blocks non-descendant from finalized checking the `db.block` database won't be useful to guard
    79→    // against known bad fork blocks, so we throw PARENT_UNKNOWN for cases (1) and (2)
    80→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    81→      code: DataColumnSidecarErrorCode.PARENT_UNKNOWN,
    82→      parentRoot,
    83→    });
    84→  }
    85→
    86→  // 8) [REJECT] The sidecar is from a higher slot than the sidecar's block's parent
    87→  if (parentBlock.slot >= blockHeader.slot) {
    88→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
    89→      code: DataColumnSidecarErrorCode.NOT_LATER_THAN_PARENT,
    90→      parentSlot: parentBlock.slot,
    91→      slot: blockHeader.slot,
    92→    });
    93→  }
    94→
    95→  // getBlockSlotState also checks for whether the current finalized checkpoint is an ancestor of the block.
    96→  // As a result, we throw an IGNORE (whereas the spec says we should REJECT for this scenario).
    97→  // this is something we should change this in the future to make the code airtight to the spec.
    98→  // 7) [REJECT] The sidecar's block's parent passes validation.
    99→  const blockState = await chain.regen
   100→    .getBlockSlotState(parentRoot, blockHeader.slot, {dontTransferCache: true}, RegenCaller.validateGossipBlock)
   101→    .catch(() => {
   102→      throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
   103→        code: DataColumnSidecarErrorCode.PARENT_UNKNOWN,
   104→        parentRoot,
   105→      });
   106→    });
   107→
   108→  // 13) [REJECT] The sidecar is proposed by the expected proposer_index for the block's slot in the context of the current
   109→  //              shuffling (defined by block_header.parent_root/block_header.slot). If the proposer_index cannot
   110→  //              immediately be verified against the expected shuffling, the sidecar MAY be queued for later processing
   111→  //              while proposers for the block's branch are calculated -- in such a case do not REJECT, instead IGNORE
   112→  //              this message.
   113→  const proposerIndex = blockHeader.proposerIndex;
   114→  const expectedProposerIndex = blockState.epochCtx.getBeaconProposer(blockHeader.slot);
   115→
   116→  if (proposerIndex !== expectedProposerIndex) {
   117→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   118→      code: DataColumnSidecarErrorCode.INCORRECT_PROPOSER,
   119→      actualProposerIndex: proposerIndex,
   120→      expectedProposerIndex,
   121→    });
   122→  }
   123→
   124→  // 5) [REJECT] The proposer signature of sidecar.signed_block_header, is valid with respect to the block_header.proposer_index pubkey.
   125→  const signatureSet = getBlockHeaderProposerSignatureSet(blockState, dataColumnSidecar.signedBlockHeader);
   126→  // Don't batch so verification is not delayed
   127→  if (
   128→    !(await chain.bls.verifySignatureSets([signatureSet], {
   129→      verifyOnMainThread: blockHeader.slot > chain.forkChoice.getHead().slot,
   130→    }))
   131→  ) {
   132→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   133→      code: DataColumnSidecarErrorCode.PROPOSAL_SIGNATURE_INVALID,
   134→    });
   135→  }
   136→
   137→  // 9) [REJECT] The current finalized_checkpoint is an ancestor of the sidecar's block
   138→  //             -- i.e. get_checkpoint_block(store, block_header.parent_root, store.finalized_checkpoint.epoch)
   139→  //                     == store.finalized_checkpoint.root
   140→  // Handled by 7)
   141→
   142→  // 10) [REJECT] The sidecar's kzg_commitments field inclusion proof is valid as verified by
   143→  //              verify_data_column_sidecar_inclusion_proof
   144→  //              TODO: Can cache result on (commitments, proof, header) in the future
   145→  const timer = metrics?.peerDas.dataColumnSidecarInclusionProofVerificationTime.startTimer();
   146→  const valid = verifyDataColumnSidecarInclusionProof(dataColumnSidecar);
   147→  timer?.();
   148→
   149→  if (!valid) {
   150→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   151→      code: DataColumnSidecarErrorCode.INCLUSION_PROOF_INVALID,
   152→      slot: dataColumnSidecar.signedBlockHeader.message.slot,
   153→      columnIdx: dataColumnSidecar.index,
   154→    });
   155→  }
   156→
   157→  const kzgProofTimer = metrics?.peerDas.dataColumnSidecarKzgProofsVerificationTime.startTimer();
   158→  // 11) [REJECT] The sidecar's column data is valid as verified by verify_data_column_sidecar_kzg_proofs
   159→  try {
   160→    await verifyDataColumnSidecarKzgProofs(
   161→      dataColumnSidecar.kzgCommitments,
   162→      Array.from({length: dataColumnSidecar.column.length}, () => dataColumnSidecar.index),
   163→      dataColumnSidecar.column,
   164→      dataColumnSidecar.kzgProofs
   165→    );
   166→  } catch {
   167→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   168→      code: DataColumnSidecarErrorCode.INVALID_KZG_PROOF,
   169→      slot: blockHeader.slot,
   170→      columnIdx: dataColumnSidecar.index,
   171→    });
   172→  } finally {
   173→    kzgProofTimer?.();
   174→  }
   175→
   176→  // 12) [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index,
   177→  //              sidecar.index) with valid header signature, sidecar inclusion proof, and kzg proof
   178→  //              -- Handled in seenGossipBlockInput
   179→}
   180→
   181→export async function validateDataColumnsSidecars(
   182→  blockSlot: Slot,
   183→  blockRoot: Root,
   184→  blockKzgCommitments: deneb.BlobKzgCommitments,
   185→  dataColumnSidecars: fulu.DataColumnSidecars,
   186→  metrics: Metrics | null,
   187→  opts: {skipProofsCheck: boolean} = {skipProofsCheck: false}
   188→): Promise<void> {
   189→  // Skip verification if there are no data columns
   190→  if (dataColumnSidecars.length === 0) {
   191→    return;
   192→  }
   193→
   194→  const commitmentBytes: Uint8Array[] = [];
   195→  const cellIndices: number[] = [];
   196→  const cells: Uint8Array[] = [];
   197→  const proofBytes: Uint8Array[] = [];
   198→
   199→  for (let sidecarsIndex = 0; sidecarsIndex < dataColumnSidecars.length; sidecarsIndex++) {
   200→    const columnSidecar = dataColumnSidecars[sidecarsIndex];
